<template>
  <v-app>
    <v-app-bar app color="primary" dark>
      <v-app-bar-nav-icon @click="drawer = !drawer" />
      <p>v 1.00</p>
      <v-toolbar-title>
        <img src="img/Unifi-logo.svg" alt="Unifi Home" class="svg-icon" />
      </v-toolbar-title>
      <v-spacer />
      <div>
        <span>Auth: {{ authStore.isAuthenticated }}</span>
        <v-btn
          v-if="authStore.isAuthenticated"
          @click="logout"
          icon
          style="background-color: red;"
        >
          <v-icon>mdi-logout</v-icon>
        </v-btn>
      </div>
    </v-app-bar>

    <v-navigation-drawer v-model="drawer" app temporary>
      <v-list nav>
        <v-list-item to="/" exact>
          <v-list-item-icon>
            <v-icon>mdi-login</v-icon>
          </v-list-item-icon>
          <v-list-item-title>Login</v-list-item-title>
        </v-list-item>

        <v-list-item
          v-for="(item, index) in filteredNavItems"
          :key="index"
          :to="item.to"
          exact
        >
          <v-list-item-icon>
            <v-icon>{{ item.icon }}</v-icon>
          </v-list-item-icon>
          <v-list-item-title>{{ item.title }}</v-list-item-title>
        </v-list-item>
      </v-list>
    </v-navigation-drawer>

    <v-main>
      <router-view />
    </v-main>

    <v-bottom-navigation v-if="authStore.isAuthenticated" app>
      <v-btn to="/about" exact>
        <span>About</span>
        <v-icon>mdi-information</v-icon>
      </v-btn>
    </v-bottom-navigation>
  </v-app>
</template>

<script setup>
import { ref, computed } from 'vue';
import { useRouter } from 'vue-router';
import { useAuthStore } from '@/stores/authStore';

const authStore = useAuthStore();
const drawer = ref(false);
const router = useRouter();

const navItems = [
  { to: '/home', title: 'Home', icon: 'mdi-home', requiresAuth: true },
  { to: '/about', title: 'About', icon: 'mdi-information', requiresAuth: true },
  { to: '/listByProject', title: 'Contact Management', icon: 'mdi-phone', requiresAuth: true },
  { to: '/list', title: 'List', icon: 'mdi-phone', requiresAuth: true },
  { to: '/main', title: 'Main', icon: 'mdi-phone', requiresAuth: true },
  { to: '/soc', title: 'Auto Show', icon: 'mdi-phone', requiresAuth: true },
  { to: '/note', title: 'Notes', icon: 'mdi-note-text', requiresAuth: true },
  { to: '/snr', title: 'Contact List V2', icon: 'mdi-account-group', requiresAuth: true },
  { to: '/cnn', title: 'CNN', icon: 'mdi-newspaper', requiresAuth: true },
  { to: '/listProject', title: 'List Project From Lead', icon: 'mdi-format-list-bulleted', requiresAuth: true },
  { to: '/importCsv', title: 'Import CSV', icon: 'mdi-file-import', requiresAuth: true },
  { to: '/displaySpreadsheetTitan', title: 'Display Spreadsheet Titan', icon: 'mdi-table', requiresAuth: true },
  { to: '/displaySpreadsheetOut', title: 'Display Spreadsheet', icon: 'mdi-table', requiresAuth: true },
  { to: '/spreadSheet', title: 'Spread Sheet In', icon: 'mdi-table', requiresAuth: true },
  { to: '/spreadSheetIn2', title: 'Spread SheetIn 2', icon: 'mdi-table', requiresAuth: true },
  { to: '/spreadSheetIn3', title: 'Spread SheetIn 3', icon: 'mdi-table', requiresAuth: true },
  { to: '/spreadSheetIn4', title: 'Spread SheetIn 4', icon: 'mdi-table', requiresAuth: true },
  { to: '/checkDuplication', title: 'Check Duplication', icon: 'mdi-content-duplicate', requiresAuth: true },
  { to: '/pasteProjectListing', title: 'List Projects', icon: 'mdi-format-list-bulleted', requiresAuth: true },
  { to: '/fillAllRecords', title: 'Fill All Records stage = "Qualify"', icon: 'mdi-database-edit', requiresAuth: true },
  { to: '/salesTalk', title: 'Sales Talk', icon: 'mdi-comment-text', requiresAuth: true },
  { to: '/speech', title: 'Speech', icon: 'mdi-microphone', requiresAuth: true },
  { to: '/recoverData', title: 'Recover Data', icon: 'mdi-database-refresh', requiresAuth: true },
  { to: '/txt2voice', title: 'Text to Voice', icon: 'mdi-microphone', requiresAuth: true },
];

const filteredNavItems = computed(() => {
  return navItems.filter(item => !item.requiresAuth || authStore.isAuthenticated);
});

function logout() {
  localStorage.setItem('authenticated', 'false');
  authStore.isAuthenticated = false;
  router.push('/');
}
</script>

<style>
.svg-icon {
  height: 32px;
}
</style>
