// src/main.js
import { createApp, provide, h } from 'vue';
import { createPinia } from 'pinia';
import App from './App.vue';
import router from './router';
import { createVuetify } from 'vuetify';
import * as components from 'vuetify/components';
import * as directives from 'vuetify/directives';
import '@mdi/font/css/materialdesignicons.css';
import 'vuetify/styles';
import { ApolloClient, InMemoryCache, createHttpLink } from '@apollo/client/core';
import { DefaultApolloClient } from '@vue/apollo-composable';

// ✅ Create Apollo Client
const httpLink = createHttpLink({
  uri: 'https://sp412b-763ef468411d.herokuapp.com/graphql',
});
const apolloClient = new ApolloClient({
  link: httpLink,
  cache: new InMemoryCache(),
});

// ✅ Create Vue App
const app = createApp({
  setup() {
    // Provide Apollo Client to all components using inject(DefaultApolloClient)
    provide(DefaultApolloClient, apolloClient);
  },
  render: () => h(App),
});

// ✅ Use Pinia
const pinia = createPinia();
app.use(pinia);

// ✅ Use Vuetify
const vuetify = createVuetify({
  components,
  directives,
});
app.use(vuetify);

// ✅ Use Router
app.use(router);

// ✅ Custom Global Method
app.config.globalProperties.cleanPhoneNumber = function (phoneNumber) {
  return phoneNumber.replace(/[\s-]/g, '');
};

// ✅ Mount App
app.mount('#app');
